# -*- coding: utf-8 -*-
# =============================================================================
# V4 YORUMLU NOT: SYMBOL INDEX
# Büyük harfli keywordleri, TOKEN_/NODE_/MIR_ sembollerini ve parse_/emit_
# fonksiyonlarını tarar. Varsayılan index/symbol_index.json mini sembol atlasıdır.
# =============================================================================
from __future__ import annotations
import argparse, re
from collections import defaultdict
from uxb_common import load_config, iter_source_files, read_text_file, detect_layer, rel_to_root, safe_json_dump, abs_from_root, now_stamp
SYMBOL_RE=re.compile(r'\b[A-Z][A-Z0-9_]{2,}\b|\b(?:TOKEN|NODE|AST|MIR|OP|KW)_[A-Za-z0-9_]+\b|\b(?:parse|emit|visit|scan|lex|build|gen|lower)_[A-Za-z0-9_]+\b', re.IGNORECASE)

def scan_symbols(config_path: str) -> None:
    cfg=load_config(config_path); index=defaultdict(list)
    if cfg.get('symbol_source_roots'):
        cfg=dict(cfg)
        cfg['source_roots']=cfg.get('symbol_source_roots')
    for p in iter_source_files(cfg):
        try: text=read_text_file(p)
        except Exception: continue
        layer=detect_layer(cfg,p,text); rel=rel_to_root(cfg,p)
        for line_no,line in enumerate(text.splitlines(), start=1):
            for m in SYMBOL_RE.finditer(line):
                sym=m.group(0)
                if len(index[sym])<10: index[sym].append({'file':rel,'line':line_no,'layer':layer,'text':line[:150]})
    out_path=abs_from_root(cfg,cfg.get('symbol_index_path','index/symbol_index.json'))
    safe_json_dump(out_path, {'created_at':now_stamp(),'symbol_count':len(index),'symbols':dict(sorted(index.items(), key=lambda kv: kv[0]))})
    print(f'{out_path.name} yazıldı. Sembol sayısı: {len(index)}')

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--config',default='config.json'); args=ap.parse_args(); scan_symbols(args.config)
if __name__=='__main__': main()

# -*- coding: utf-8 -*-
# =============================================================================
# V4 YORUMLU NOT: ORTAK ALT YAPI
# Bu modül config okuma, dosya tarama, dosya okuma, chunk üretme ve katman
# tahmini gibi bütün araçların ortak kullandığı fonksiyonları içerir.
# cfg: dict; config.json ayarlarıdır. Path: pathlib.Path dosya/klasör yoludur.
# Chunk sözlüğü: text, line_start, line_end, char_start, char_end alanlarını taşır.
# =============================================================================
from __future__ import annotations
import json, re, time, hashlib, fnmatch
from pathlib import Path
from typing import Dict, Iterable, List, Any

TEXT_EXTENSIONS_DEFAULT = {'.bas','.bi','.inc','.c','.cpp','.h','.hpp','.asm','.s','.nasm','.js','.ts','.html','.css','.py','.ps1','.bat','.cmd','.md','.txt','.json','.csv','.log'}

def load_config(config_path: str | Path = 'config.json') -> Dict[str, Any]:
    p = Path(config_path).resolve()
    if not p.exists():
        raise FileNotFoundError(f'Config bulunamadı: {p}')
    cfg = json.loads(p.read_text(encoding='utf-8'))
    cfg['_config_path'] = str(p)
    cfg['_root'] = str(p.parent)
    return cfg

def abs_from_root(cfg: Dict[str, Any], path_value: str | Path) -> Path:
    p = Path(path_value)
    return p if p.is_absolute() else Path(cfg['_root']) / p

def rel_to_root(cfg: Dict[str, Any], path_value: str | Path) -> str:
    p = Path(path_value).resolve(); root = Path(cfg['_root']).resolve()
    try: return str(p.relative_to(root)).replace('\\','/')
    except ValueError: return str(p).replace('\\','/')

def ensure_dirs(cfg: Dict[str, Any]) -> None:
    abs_from_root(cfg, cfg.get('chroma_path','index/chroma_db')).mkdir(parents=True, exist_ok=True)
    (Path(cfg['_root'])/'index').mkdir(exist_ok=True)
    (Path(cfg['_root'])/'logs').mkdir(exist_ok=True)

def is_excluded(path: Path, exclude_dirs: List[str]) -> bool:
    parts = {x.lower() for x in path.parts}
    return any(x.lower() in parts for x in exclude_dirs)

def iter_source_files(cfg: Dict[str, Any]) -> Iterable[Path]:
    roots = cfg.get('source_roots') or ['kaynaklar']
    supported = {x.lower() for x in cfg.get('supported_extensions', list(TEXT_EXTENSIONS_DEFAULT))}
    exclude = cfg.get('exclude_dirs', [])
    exclude_file_globs = cfg.get('exclude_file_globs', [])
    for rv in roots:
        rp = abs_from_root(cfg, rv)
        if not rp.exists(): continue
        for p in rp.rglob('*'):
            if not p.is_file():
                continue
            if is_excluded(p, exclude):
                continue
            if p.suffix.lower() not in supported:
                continue
            if any(fnmatch.fnmatch(p.name, pat) for pat in exclude_file_globs):
                continue
            name_l = p.name.lower()
            if name_l.startswith('buraya_') or 'placeholder' in name_l or 'kopyala' in name_l:
                continue
            yield p

def read_text_file(path: Path) -> str:
    for enc in ('utf-8-sig','utf-8','cp1254','cp1252','latin-1'):
        try: return path.read_text(encoding=enc, errors='strict')
        except UnicodeDecodeError: pass
        except Exception: break
    return path.read_text(encoding='utf-8', errors='replace')

def sha1_text(text: str) -> str:
    return hashlib.sha1(text.encode('utf-8', errors='ignore')).hexdigest()

def detect_language_by_ext(path: Path) -> str:
    return {'.bas':'freebasic/basic','.bi':'freebasic_header','.inc':'include','.c':'c','.cpp':'cpp','.h':'c_header','.hpp':'cpp_header','.asm':'asm','.s':'asm','.nasm':'nasm','.js':'javascript','.ts':'typescript','.html':'html','.css':'css','.py':'python','.ps1':'powershell','.bat':'batch','.cmd':'batch','.md':'markdown','.txt':'text','.json':'json','.csv':'csv','.log':'log'}.get(path.suffix.lower(),'text')

def detect_layer(cfg: Dict[str, Any], path: Path, text_hint: str = '') -> str:
    joined = (rel_to_root(cfg,path)+'\n'+text_hint[:1000]).lower()
    rules = cfg.get('layer_path_rules', {})
    for layer in cfg.get('layer_order', []):
        if any(term.lower() in joined for term in rules.get(layer, [])):
            return layer
    return 'unknown'

def line_number_at_offset(text: str, offset: int) -> int:
    return text.count('\n', 0, max(0, offset)) + 1

def make_chunks(cfg: Dict[str, Any], path: Path, text: str) -> List[Dict[str, Any]]:
    chunk_chars = max(500, int(cfg.get('chunk_chars',1800)))
    overlap = max(0, int(cfg.get('chunk_overlap',250)))
    if overlap >= chunk_chars: overlap = chunk_chars // 5
    chunks=[]; n=len(text); start=0; idx=0
    while start < n:
        end = min(n, start + chunk_chars)
        if end < n:
            nl = text.find('\n', end, min(n, end+250))
            if nl != -1: end = nl + 1
        piece = text[start:end].strip()
        if piece:
            chunks.append({'chunk_index':idx,'text':piece,'line_start':line_number_at_offset(text,start),'line_end':line_number_at_offset(text,end),'char_start':start,'char_end':end})
            idx += 1
        if end >= n: break
        start = max(0, end - overlap)
    return chunks

def safe_json_dump(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')

def now_stamp() -> str:
    return time.strftime('%Y-%m-%d %H:%M:%S')

