# -*- coding: utf-8 -*-
# =============================================================================
# V4 YORUMLU NOT: CHROMADB INDEX
# Kaynak dosyaları okur, make_chunks ile parçalara böler, Ollama embedding üretir,
# ChromaDB PersistentClient ile index/chroma_db altına kalıcı olarak yazar.
# ids/docs/metas listeleri Chroma upsert işlemine gider.
# =============================================================================
from __future__ import annotations
import argparse, json, sys
from pathlib import Path
from typing import List, Any
try:
    import chromadb
    from chromadb.errors import NotFoundError
except Exception:
    print('HATA: chromadb kurulu değil. Önce scripts\\install_requirements.bat çalıştır.', file=sys.stderr); raise
from uxb_common import load_config, abs_from_root, ensure_dirs, iter_source_files, read_text_file, make_chunks, detect_layer, detect_language_by_ext, rel_to_root, sha1_text, safe_json_dump, now_stamp
from uxb_ollama import embed_texts, OllamaError

def batched(items: List[Any], size: int):
    for i in range(0, len(items), size): yield items[i:i+size]

def get_or_create_collection(client: Any, name: str) -> Any:
    try:
        return client.get_collection(name=name)
    except NotFoundError:
        return client.get_or_create_collection(name=name, metadata={'hnsw:space':'cosine'})

def load_old_manifest(path: Path) -> dict[str, dict[str, Any]]:
    if not path.exists():
        return {}
    try:
        payload=json.loads(path.read_text(encoding='utf-8-sig'))
        return {row['file']:row for row in payload.get('files',[]) if row.get('file')}
    except Exception as exc:
        print(f'[UYARI] Eski manifest okunamadı; güvenli tam upsert yapılacak: {exc}')
        return {}

def build_index(config_path: str, rebuild: bool=False) -> None:
    cfg=load_config(config_path); ensure_dirs(cfg)
    chroma_path=abs_from_root(cfg, cfg.get('chroma_path','index/chroma_db')); name=cfg.get('collection_name','uxb_hybrid_v1')
    print(f'[UXB-RAG] Chroma path: {chroma_path}'); print(f'[UXB-RAG] Collection: {name}'); print(f'[UXB-RAG] Embed model: {cfg.get("embed_model")}')
    client=chromadb.PersistentClient(path=str(chroma_path))
    if rebuild:
        try:
            client.delete_collection(name)
            print('[UXB-RAG] Eski collection silindi.')
        except Exception as exc:
            print(f'[UXB-RAG] Eski collection temizlenemedi: {exc}')
    collection=get_or_create_collection(client, name)
    manifest_path=abs_from_root(cfg,cfg.get('manifest_path','index/file_manifest.json'))
    old_manifest={} if rebuild else load_old_manifest(Path(manifest_path))
    files=list(iter_source_files(cfg)); print(f'[UXB-RAG] Bulunan dosya: {len(files)}')
    ids=[]; docs=[]; metas=[]; manifest=[]
    current_files=set(); changed_files=[]; unchanged=0
    for p in files:
        try: text=read_text_file(p)
        except Exception as e: print(f'[UYARI] Okunamadı: {p} -> {e}'); continue
        if not text.strip(): continue
        rel=rel_to_root(cfg,p); layer=detect_layer(cfg,p,text); lang=detect_language_by_ext(p); fh=sha1_text(text)
        current_files.add(rel)
        old=old_manifest.get(rel)
        if old and old.get('sha1') == fh:
            manifest.append(old)
            unchanged += 1
            continue
        chunks=make_chunks(cfg,p,text)
        manifest.append({'file':rel,'layer':layer,'language':lang,'sha1':fh,'chars':len(text),'chunks':len(chunks)})
        changed_files.append(rel)
        for ch in chunks:
            cid=sha1_text(f"{rel}|{ch['chunk_index']}|{fh}|{ch['line_start']}|{ch['line_end']}")
            ids.append(cid); docs.append(ch['text']); metas.append({'file':rel,'layer':layer,'language':lang,'chunk_index':ch['chunk_index'],'line_start':ch['line_start'],'line_end':ch['line_end'],'sha1':fh})
    deleted_files=sorted(set(old_manifest)-current_files)
    for rel in changed_files + deleted_files:
        collection.delete(where={'file':rel})
    print(f'[UXB-RAG] Değişmeyen dosya: {unchanged}')
    print(f'[UXB-RAG] Yeni/değişen dosya: {len(changed_files)}')
    print(f'[UXB-RAG] Silinen dosya: {len(deleted_files)}')
    print(f'[UXB-RAG] Üretilen yeni chunk: {len(ids)}')
    if not ids:
        safe_json_dump(manifest_path, {'created_at':now_stamp(),'collection':name,'mode':'incremental','files':manifest})
        print('[UXB-RAG] Yeni embedding gerekmiyor; eski vektörler korundu.')
        return
    done=0
    batch_size = max(1, int(cfg.get('embedding_batch_size', 16)))
    for inds in batched(list(range(len(ids))), batch_size):
        batch_docs=[docs[i] for i in inds]
        try: embs=embed_texts(cfg, batch_docs)
        except OllamaError as e:
            print(f'[HATA] {e}', file=sys.stderr); print('Önce: ollama pull nomic-embed-text', file=sys.stderr); raise SystemExit(2)
        for attempt in range(2):
            try:
                collection=get_or_create_collection(client, name)
                collection.upsert(ids=[ids[i] for i in inds], documents=batch_docs, metadatas=[metas[i] for i in inds], embeddings=embs)
                break
            except NotFoundError:
                print(f'[UXB-RAG] Koleksiyon yeniden oluşturuluyor ({attempt+1}/2)...')
                if attempt == 1:
                    raise
        done += len(inds); print(f'[UXB-RAG] Indexlenen: {done}/{len(ids)}')
    safe_json_dump(manifest_path, {'created_at':now_stamp(),'collection':name,'mode':'rebuild' if rebuild else 'incremental','files':manifest})
    print('[UXB-RAG] Tamamlandı.')

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--config', default='config.json')
    ap.add_argument('--rebuild', action='store_true', help='Koleksiyonu silip her şeyi baştan vektörleştirir.')
    args=ap.parse_args()
    build_index(args.config,args.rebuild)
if __name__ == '__main__': main()

